# Docs

Human-reviewed project knowledge that agents can't infer from the code. `CLAUDE.md` points here.

- [`decisions/`](decisions/): architecture decision records (ADRs), one file per decision, numbered and never
  renumbered. To reverse a decision, add a new ADR that supersedes the old one.

Add a folder only when a document needs it. If the code can answer a question, don't write a doc for it.
{
  "name": "gol2",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "lint": "oxlint",
    "format": "oxfmt",
    "format:check": "oxfmt --check",
    "lint:md": "markdownlint-cli2",
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview",
    "test": "vitest run",
    "typecheck": "tsc --noEmit -p tsconfig.json && tsc --noEmit -p tsconfig.node.json",
    "check": "npm run -s format:check && npm run -s lint && npm run -s lint:md && npm run -s check:board && npm run -s typecheck && npm test",
    "check:board": "tsx scripts/check-board.ts"
  },
  "devDependencies": {
    "@types/node": "22.20.4",
    "markdownlint-cli2": "0.23.3",
    "markdownlint-rule-relative-links": "5.1.3",
    "oxfmt": "0.70.0",
    "oxlint": "1.85.0",
    "tsx": "4.23.15",
    "typescript": "7.0.2",
    "vite": "8.3.1",
    "vitest": "5.0.1",
    "yaml": "2.9.1"
  },
  "engines": {
    "node": ">=22"
  }
}
{
  // Formatting (including line wrapping) is oxfmt's job; markdownlint checks structure.
  "config": {
    "MD013": false,
    "relative-links": true,
  },
  "customRules": ["markdownlint-rule-relative-links"],
  "globs": ["**/*.md"],
  // Also skips .gitignore'd paths, such as agent worktrees under .claude/worktrees/.
  "gitignore": true,
  "ignores": ["**/node_modules/**", "**/dist/**"],
}
{
  "hooks": {
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "\"$CLAUDE_PROJECT_DIR/node_modules/.bin/tsx\" \"$CLAUDE_PROJECT_DIR/.claude/hooks/snapshot-tree.ts\""
          }
        ]
      }
    ],
    "SubagentStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "\"$CLAUDE_PROJECT_DIR/node_modules/.bin/tsx\" \"$CLAUDE_PROJECT_DIR/.claude/hooks/snapshot-tree.ts\""
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "\"$CLAUDE_PROJECT_DIR/node_modules/.bin/tsx\" \"$CLAUDE_PROJECT_DIR/.claude/hooks/stop-check.ts\"",
            "timeout": 300
          }
        ]
      }
    ],
    "SubagentStop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "\"$CLAUDE_PROJECT_DIR/node_modules/.bin/tsx\" \"$CLAUDE_PROJECT_DIR/.claude/hooks/stop-check.ts\"",
            "timeout": 300
          }
        ]
      }
    ]
  }
}
